/**
 * Toolkit content (src/data/toolkit.json, generated by scripts/import-toolkit.mjs from
 * docs/research/toolkit.md): the team's mental model as four steps, and tools with sourced examples.
 * Validated at build time, like the sector content.
 */
import { z } from 'zod';
import raw from '../data/toolkit.json';

const Source = z.object({ publisher: z.string(), title: z.string(), url: z.string().url(), published: z.string().optional() });
const Example = z.object({ place: z.string(), year: z.string(), what: z.string(), sources: z.array(Source).min(1) });
const Step = z.object({ n: z.number(), id: z.string(), name: z.string(), points: z.array(z.string()).min(1) });
const Tool = z.object({
  id: z.string(),
  name: z.string(),
  oneliner: z.string(),
  steps: z.array(z.number().int().min(1).max(4)).min(1),
  status: z.enum(['in_place', 'piloting', 'proposed']),
  examples: z.array(Example),
  review: z.literal('pending').optional(),
  body: z.string().optional(),
  sector: z.object({ id: z.string(), slug: z.string(), name: z.string() }).optional(),
}).refine((t) => t.status === 'proposed' || t.examples.length > 0, { message: 'Every tool in place or piloting needs a sourced example' });

const Toolkit = z.object({ as_of: z.string(), steps: z.array(Step).length(4), tools: z.array(Tool).min(1) });
export const toolkit = Toolkit.parse(raw);
export type ToolkitTool = z.infer<typeof Tool>;
export const STATUS_LABEL: Record<ToolkitTool['status'], string> = { in_place: 'In place', piloting: 'Piloting', proposed: 'Proposed by the team' };
